import{_ as a,o as n,c as s,a5 as i}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"81. The C Standard Timeline (C89 to C23)","description":"The Little Book of C — 81. The C Standard Timeline (C89 to C23)","frontmatter":{"title":"81. The C Standard Timeline (C89 to C23)","date":"2026-07-04","categories":["C 教程"],"tags":["C","Little Book of C","Portable and Modern C"],"description":"The Little Book of C — 81. The C Standard Timeline (C89 to C23)","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","section":81,"sidebarWeight":81,"lang":"en-US","alternateEn":"/posts/c教程/en-US/09-Portable and Modern C/081-The C Standard Timeline (C89 to C23)","alternateZh":"/posts/c教程/zh-CN/09-可移植与现代 C/081-The C Standard Timeline (C89 to C23)"},"headers":[],"relativePath":"posts/c教程/en-US/09-Portable and Modern C/081-The C Standard Timeline (C89 to C23).md","filePath":"posts/c教程/en-US/09-Portable and Modern C/081-The C Standard Timeline (C89 to C23).md","lastUpdated":1790163617000}'),t={name:"posts/c教程/en-US/09-Portable and Modern C/081-The C Standard Timeline (C89 to C23).md"};function o(l,e,p,d,r,c){return n(),s("div",null,[...e[0]||(e[0]=[i(`<p>[中文版本](/posts/c教程/zh-CN/09-可移植与现代 C/081-The C Standard Timeline (C89 to C23))</p><p>C has been around for more than fifty years, and it has evolved slowly and carefully. Every version of the C standard improves the language while keeping backward compatibility with decades of existing code.</p><p>Understanding the timeline of C standards helps you write portable, modern code and know which features are safe to use in your target environments.</p><h4 id="step-1-the-beginning-k-r-c-1972–1989" tabindex="-1">Step 1. The Beginning, K&amp;R C (1972–1989) <a class="header-anchor" href="#step-1-the-beginning-k-r-c-1972–1989" aria-label="Permalink to &quot;Step 1. The Beginning, K&amp;R C (1972–1989)&quot;">​</a></h4><p>C was born at Bell Labs in the early 1970s, developed by Dennis Ritchie as a systems programming language for Unix. The first book, The C Programming Language by Kernighan and Ritchie (1978), informally defined “K&amp;R C.”</p><p>Key Traits:</p><ul><li>No standardization yet.</li><li>Implicit function declarations.</li><li>No<code>void</code> type for functions without return.</li><li>No function prototypes (parameters not type-checked).</li><li>Header files were optional.</li></ul><p>Example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>main() {</span></span>
<span class="line"><span>    printf(&quot;Hello, world\\n&quot;);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>It was simple, direct, and dangerous, but it worked.</p><h4 id="step-2-ansi-c-c89-c90" tabindex="-1">Step 2. ANSI C (C89 / C90) <a class="header-anchor" href="#step-2-ansi-c-c89-c90" aria-label="Permalink to &quot;Step 2. ANSI C (C89 / C90)&quot;">​</a></h4><p>In 1989, C became standardized by ANSI (and in 1990 by ISO). This version, C89/C90, unified compiler behavior and made C portable across systems.</p><p>Key Features:</p><ul><li>Function prototypes (<code>int add(int, int);</code>)</li><li>Standard headers (<code>&lt;stdio.h&gt;</code>,<code>&lt;stdlib.h&gt;</code>,<code>&lt;string.h&gt;</code>)</li><li><code>void</code> keyword</li><li>Type qualifiers:<code>const</code>,<code>volatile</code></li><li>New library functions (<code>memcpy</code>,<code>qsort</code>,<code>assert</code>)</li><li>Formalized the standard library</li><li>Single-line comments were still not supported (use<code>/* */</code>)</li></ul><p>Tiny Code:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int add(int a, int b) { return a + b; }</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    printf(&quot;%d\\n&quot;, add(2, 3));</span></span>
<span class="line"><span>}</span></span></code></pre></div><h4 id="step-3-c95-iso-amendment" tabindex="-1">Step 3. C95 (ISO Amendment) <a class="header-anchor" href="#step-3-c95-iso-amendment" aria-label="Permalink to &quot;Step 3. C95 (ISO Amendment)&quot;">​</a></h4><p>A minor update that refined C90, rarely mentioned but still significant.</p><p>Added:</p><ul><li>Wide character support (<code>&lt;wchar.h&gt;</code>)</li><li>Multibyte strings</li><li>More internationalization utilities</li><li>Macros like<code>__STDC_VERSION__</code></li></ul><p>It paved the way for Unicode support in later versions.</p><h4 id="step-4-c99-modernization-begins" tabindex="-1">Step 4. C99, Modernization Begins <a class="header-anchor" href="#step-4-c99-modernization-begins" aria-label="Permalink to &quot;Step 4. C99, Modernization Begins&quot;">​</a></h4><p>C99 (published in 1999) was the biggest update since the beginning.</p><p>Major Improvements:</p><ul><li><code>//</code> single-line comments</li><li>Variable declarations anywhere</li><li>Inline functions</li><li><code>long long</code>(64-bit integer)</li><li><code>stdbool.h</code> for<code>bool</code>,<code>true</code>,<code>false</code></li><li><code>stdint.h</code> for fixed-width integers (<code>int32_t</code>,<code>uint64_t</code>)</li><li>Designated initializers and compound literals</li><li>Flexible array members</li><li><code>snprintf</code> safer string formatting</li><li>Variable-length arrays (VLAs)</li></ul><p>Tiny Code:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdbool.h&gt;</span></span>
<span class="line"><span>#include &lt;stdint.h&gt;</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    bool done = false;</span></span>
<span class="line"><span>    uint64_t sum = 0;</span></span>
<span class="line"><span>    for (int i = 0; i &lt; 5; i++)</span></span>
<span class="line"><span>        sum += i;</span></span>
<span class="line"><span>    printf(&quot;%llu\\n&quot;, (unsigned long long)sum);</span></span>
<span class="line"><span>    return done;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>C99 made C feel modern, introducing safer and more expressive syntax.</p><h4 id="step-5-c11-concurrency-and-safety" tabindex="-1">Step 5. C11, Concurrency and Safety <a class="header-anchor" href="#step-5-c11-concurrency-and-safety" aria-label="Permalink to &quot;Step 5. C11, Concurrency and Safety&quot;">​</a></h4><p>Released in 2011, C11 added better threading and safety mechanisms.</p><p>Key Additions:</p><ul><li><code>_Thread_local</code> storage specifier</li><li><code>&lt;threads.h&gt;</code> for portable threads, mutexes, condition variables</li><li><code>_Atomic</code> for atomic operations</li><li><code>_Static_assert</code> for compile-time checks</li><li>Bounds-checked functions (<code>strcpy_s</code>,<code>memcpy_s</code>)</li><li>Optional Annex K for safer standard library functions</li><li>Improved Unicode and wide character support</li></ul><p>Tiny Code:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;threads.h&gt;</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int run(void *arg) {</span></span>
<span class="line"><span>    printf(&quot;Hello from thread %d\\n&quot;, *(int *)arg);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int id = 1;</span></span>
<span class="line"><span>    thrd_t t;</span></span>
<span class="line"><span>    thrd_create(&amp;t, run, &amp;id);</span></span>
<span class="line"><span>    thrd_join(t, NULL);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>C11 made C safer and concurrency-aware, though not all compilers implemented<code>&lt;threads.h&gt;</code> fully.</p><h4 id="step-6-c17-a-k-a-c18-the-refinement" tabindex="-1">Step 6. C17 (a.k.a. C18), The Refinement <a class="header-anchor" href="#step-6-c17-a-k-a-c18-the-refinement" aria-label="Permalink to &quot;Step 6. C17 (a.k.a. C18), The Refinement&quot;">​</a></h4><p>Officially ISO/IEC 9899:2018 (published in 2018), C17 fixed inconsistencies and bugs in C11 but didn’t add new features.</p><p>Highlights:</p><ul><li>Clarifications to atomics, macros, and UB rules.</li><li>Improved compatibility with C++ compilers.</li><li>Bug fixes in the standard library.</li><li><code>__STDC_VERSION__</code> is<code>201710L</code>.</li></ul><p>It’s the default “stable” standard for modern C codebases.</p><h4 id="step-7-c23-the-latest-standard" tabindex="-1">Step 7. C23, The Latest Standard <a class="header-anchor" href="#step-7-c23-the-latest-standard" aria-label="Permalink to &quot;Step 7. C23, The Latest Standard&quot;">​</a></h4><p>C23 is the most recent (published in 2024), continuing modernization without breaking backward compatibility.</p><p>Major Features:</p><ul><li><code>typeof</code>(like in GCC)</li><li><code>nullptr</code> keyword</li><li><code>static_assert</code>(alias for<code>_Static_assert</code>)</li><li>UTF-8 string literals:<code>u8&quot;Hello&quot;</code></li><li>New standard attributes (<code>[[maybe_unused]]</code>,<code>[[nodiscard]]</code>)</li><li><code>constexpr</code>-like features (<code>constexpr</code> functions are planned)</li><li>Better Unicode and formatting APIs</li><li>Safer library extensions</li><li>Improved interoperability with C++</li></ul><p>Tiny Code:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int x = 10;</span></span>
<span class="line"><span>    [[maybe_unused]] int y = 20;</span></span>
<span class="line"><span>    static_assert(sizeof(int) == 4, &quot;Expected 4-byte int&quot;);</span></span>
<span class="line"><span>    printf(&quot;%d\\n&quot;, x);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>C23 brings C closer to modern C++ and Rust-style safety while staying simple and lightweight.</p><h4 id="step-8-checking-your-compiler-s-version" tabindex="-1">Step 8. Checking Your Compiler’s Version <a class="header-anchor" href="#step-8-checking-your-compiler-s-version" aria-label="Permalink to &quot;Step 8. Checking Your Compiler’s Version&quot;">​</a></h4><p>You can check your compiler’s supported C standard using:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -dM -E - &lt; /dev/null | grep __STDC_VERSION__</span></span></code></pre></div><p>Common outputs:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>199901L  → C99  </span></span>
<span class="line"><span>201112L  → C11  </span></span>
<span class="line"><span>201710L  → C17  </span></span>
<span class="line"><span>202311L  → C23</span></span></code></pre></div><p>Or compile with:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -std=c99 program.c</span></span>
<span class="line"><span>gcc -std=c11 program.c</span></span>
<span class="line"><span>gcc -std=c23 program.c</span></span></code></pre></div><h4 id="step-9-compatibility-and-portability-tips" tabindex="-1">Step 9. Compatibility and Portability Tips <a class="header-anchor" href="#step-9-compatibility-and-portability-tips" aria-label="Permalink to &quot;Step 9. Compatibility and Portability Tips&quot;">​</a></h4><ul><li>Always declare the standard explicitly:<code>-std=c11</code> or<code>-std=c17</code>.</li><li>Avoid compiler-specific extensions unless guarded with<code>#ifdef __GNUC__</code>.</li><li>Use standard headers like<code>&lt;stdint.h&gt;</code> and<code>&lt;stdbool.h&gt;</code>.</li><li>When writing libraries, prefer the lowest standard that supports your needs.</li><li>Add<code>_Static_assert</code> or<code>#error</code> for unsupported standards.</li></ul><h4 id="step-10-tiny-code-version-detector" tabindex="-1">Step 10. Tiny Code: Version Detector <a class="header-anchor" href="#step-10-tiny-code-version-detector" aria-label="Permalink to &quot;Step 10. Tiny Code: Version Detector&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>#if __STDC_VERSION__ &gt;= 202311L</span></span>
<span class="line"><span>    printf(&quot;C23 or newer\\n&quot;);</span></span>
<span class="line"><span>#elif __STDC_VERSION__ &gt;= 201710L</span></span>
<span class="line"><span>    printf(&quot;C17\\n&quot;);</span></span>
<span class="line"><span>#elif __STDC_VERSION__ &gt;= 201112L</span></span>
<span class="line"><span>    printf(&quot;C11\\n&quot;);</span></span>
<span class="line"><span>#elif __STDC_VERSION__ &gt;= 199901L</span></span>
<span class="line"><span>    printf(&quot;C99\\n&quot;);</span></span>
<span class="line"><span>#else</span></span>
<span class="line"><span>    printf(&quot;C90 or earlier\\n&quot;);</span></span>
<span class="line"><span>#endif</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Compile and run to see what your compiler supports.</p><h4 id="why-it-matters" tabindex="-1">Why It Matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why It Matters&quot;">​</a></h4><p>C’s evolution shows its unique philosophy: change slowly, but never break old code. Knowing which standard you target means you can use modern features confidently, without losing portability.</p><h4 id="try-it-yourself" tabindex="-1">Try It Yourself <a class="header-anchor" href="#try-it-yourself" aria-label="Permalink to &quot;Try It Yourself&quot;">​</a></h4><ol><li>Write the version detector program above and run it with<code>-std=c99</code>,<code>-std=c11</code>, and<code>-std=c23</code>.</li><li>Experiment with<code>_Static_assert</code> and<code>_Thread_local</code>, see which standards support them.</li><li>Try compiling a small thread example using<code>&lt;threads.h&gt;</code>.</li><li>Look up your compiler’s documentation to see which features of C23 are implemented.</li><li>Pick one feature (like<code>[[nodiscard]]</code>) and use it in a tiny project.</li></ol><p>Next, you’ll explore portability and endianness, the invisible details that determine how your C programs behave across different machines and architectures.</p>`,64)])])}const m=a(t,[["render",o]]);export{u as __pageData,m as default};
